using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Currencies.Commands.UpdateCurrency;
public sealed class UpdateCurrencyCommandHandler(IRepository<Currency,Guid> repository):IRequestHandler<UpdateCurrencyCommand>{public async Task Handle(UpdateCurrencyCommand r,CancellationToken ct){var e=await repository.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(Currency),r.Id);byte[] rv;try{rv=Convert.FromBase64String(r.Request.RowVersion);}catch(FormatException ex){throw new ConcurrencyException("Currency row version is invalid.",ex);}if(!rv.SequenceEqual(e.RowVersion))throw new ConcurrencyException("Currency was modified by another user.");e.Update(r.Request.NameAr,r.Request.NameEn,r.Request.Symbol,r.Request.DecimalPlaces,r.Request.IsActive);repository.Update(e);}}
